head.b:skin:
:root{--bg:#070911;--panel:rgba(18,23,39,.82);--line:rgba(112,145,255,.2);--blue:#7296ff;--cyan:#76e5ff;--gold:#e8c878;--muted:#aab3ca;--text:#f5f7ff;--red:#ff617d;--radius:22px}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:radial-gradient(ellipse at 80% 0%,#17234b 0,transparent 38%),radial-gradient(ellipse at 5% 35%,#21142f 0,transparent 35%),var(--bg);color:var(--text);font-family:Tahoma,Arial,sans-serif;line-height:1.7}a{color:inherit;text-decoration:none}button{font:inherit;cursor:pointer}.wrap{width:min(1180px,92%);margin:auto}.nav{position:sticky;top:0;z-index:10;background:#070911d9;backdrop-filter:blur(18px);border-bottom:1px solid var(--line)}.navin{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:14px 0}.brand{display:flex;align-items:center;gap:12px;font-weight:900;letter-spacing:.3px}.brandmark{width:43px;height:43px;border-radius:14px;display:grid;place-items:center;background:linear-gradient(145deg,#1c3269,#111524);border:1px solid #7b9dff66;box-shadow:0 0 26px #557aff30;font-size:23px}.brand small{display:block;color:var(--muted);font-size:11px;font-weight:500}.navlinks{display:flex;gap:18px;color:#d3d9ee;font-size:13px}.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:11px 16px;border-radius:13px;border:1px solid #829eff55;background:linear-gradient(135deg,#3458b8,#202c58);color:white;font-weight:800;box-shadow:0 8px 28px #355dba24;transition:.2s}.btn:hover{transform:translateY(-2px);filter:brightness(1.12)}.btn.secondary{background:#ffffff08;border-color:var(--line);box-shadow:none}.hero{padding:65px 0 38px;display:grid;grid-template-columns:1.1fr .9fr;align-items:center;gap:32px}.eyebrow{display:inline-flex;gap:8px;align-items:center;color:var(--cyan);font-size:12px;border:1px solid #76e5ff3b;background:#76e5ff0d;border-radius:100px;padding:7px 12px}.hero h1{font-size:clamp(34px,5vw,62px);line-height:1.2;margin:18px 0 14px;letter-spacing:-1.5px}.hero h1 span{background:linear-gradient(90deg,#fff,#8db4ff 45%,#d3b9ff);background-clip:text;color:transparent}.hero p{color:var(--muted);max-width:650px;margin:0 0 22px}.actions{display:flex;flex-wrap:wrap;gap:10px}.heroart{min-height:300px;position:relative;display:grid;place-items:center;overflow:hidden;border:1px solid var(--line);border-radius:30px;background:radial-gradient(circle at 50% 42%,#334e9b80,transparent 43%),linear-gradient(145deg,#121a32,#0b0e19);box-shadow:inset 0 0 70px #4b65b21c,0 24px 80px #0006}.moon{width:165px;height:165px;border-radius:50%;background:radial-gradient(circle at 33% 28%,#eff5ff,#94b8ff 34%,#354a89 68%,#11182b);box-shadow:0 0 35px #789dff99,0 0 110px #5b79ff3d;position:relative}.moon:after{content:'🐺';position:absolute;font-size:90px;left:50%;top:50%;transform:translate(-50%,-45%);filter:drop-shadow(0 12px 12px #000)}.orbit{position:absolute;width:255px;height:255px;border:1px solid #91b1ff38;border-radius:50%;animation:spin 24s linear infinite}.orbit:before{content:'✦';position:absolute;top:22px;left:30px;color:#a9dfff;font-size:20px}.orbit.two{width:315px;height:315px;border-style:dashed;animation-direction:reverse;opacity:.5}@keyframes spin{to{transform:rotate(360deg)}}.section{padding:34px 0}.sectionhead{display:flex;justify-content:space-between;align-items:end;gap:16px;margin-bottom:18px}.sectionhead h2{margin:0;font-size:25px}.sectionhead p{margin:3px 0 0;color:var(--muted);font-size:13px}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.panel{border:1px solid var(--line);background:var(--panel);backdrop-filter:blur(14px);border-radius:var(--radius);padding:20px;box-shadow:0 14px 42px #0002}.statlabel{color:var(--muted);font-size:13px}.statvalue{font-size:28px;font-weight:900;margin-top:5px}.statusrow{display:flex;align-items:center;gap:8px;color:#b8c4e4;font-size:12px}.dot{width:8px;height:8px;border-radius:50%;background:#55e4a0;box-shadow:0 0 12px #55e4a0}.dot.off{background:#ff647c;box-shadow:0 0 12px #ff647c}.livegrid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.leaderboard{overflow:hidden;padding:0}.tablehead,.playerrow{display:grid;grid-template-columns:55px 1fr 90px 90px;gap:12px;align-items:center;padding:13px 18px}.tablehead{font-size:12px;color:var(--muted);background:#ffffff06;border-bottom:1px solid var(--line)}.playerrow{border-bottom:1px solid #ffffff0b}.playerrow:last-child{border-bottom:0}.ranknum{font-weight:900;color:var(--gold)}.playername{display:flex;align-items:center;gap:10px;min-width:0}.avatar{width:36px;height:36px;border-radius:50%;object-fit:cover;background:#202b4b;border:1px solid #7797ff55}.name{font-weight:800;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.sub{color:var(--muted);font-size:11px}.score{font-weight:800}.rolesgrid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.rolecard{padding:0;overflow:hidden;transition:.25s}.rolecard:hover{transform:translateY(-4px);border-color:#8aa8ff88;box-shadow:0 18px 50px #314eaa25}.roleimage{height:165px;background:radial-gradient(circle at 50% 30%,#2d3e72,#0a0d17 70%);display:grid;place-items:center;overflow:hidden}.roleimage img{width:100%;height:100%;object-fit:cover}.rolebody{padding:16px}.rolemeta{display:flex;justify-content:space-between;align-items:center;gap:8px}.pill{border:1px solid var(--line);color:#bac8f5;border-radius:100px;padding:3px 8px;font-size:10px}.rolebody h3{margin:10px 0 5px;font-size:17px}.rolebody p{margin:0;color:var(--muted);font-size:12px}.loading,.empty{color:var(--muted);text-align:center;padding:24px}.footer{margin-top:45px;border-top:1px solid var(--line);padding:26px 0;color:var(--muted);font-size:12px}.footin{display:flex;justify-content:space-between;gap:16px;flex-wrap:wrap}.toast{position:fixed;bottom:18px;left:18px;z-index:20;background:#151c2d;border:1px solid var(--line);border-radius:12px;padding:12px 16px;color:white;display:none;max-width:90vw}.error{color:#ff9cab}.smallnote{color:var(--muted);font-size:11px}.refresh{background:transparent;border:1px solid var(--line);color:#dbe4ff;padding:7px 10px;border-radius:10px}
@media(max-width:850px){.hero{grid-template-columns:1fr;padding-top:38px}.heroart{min-height:260px}.rolesgrid{grid-template-columns:repeat(2,1fr)}.livegrid{grid-template-columns:repeat(2,1fr)}.grid{grid-template-columns:1fr}.navlinks{display:none}}@media(max-width:480px){.rolesgrid{grid-template-columns:1fr 1fr;gap:9px}.roleimage{height:125px}.rolebody{padding:12px}.rolebody h3{font-size:14px}.rolebody p{font-size:11px}.tablehead,.playerrow{grid-template-columns:32px 1fr 55px 55px;gap:7px;padding:11px 9px}.avatar{width:29px;height:29px}.sub{display:none}.score{font-size:12px}.hero h1{font-size:36px}.panel{padding:15px}}

/* Blogger post area */
.blog-posts{margin:30px auto;max-width:1180px}.post-outer,.post{background:rgba(18,23,39,.82);border:1px solid rgba(112,145,255,.2);border-radius:20px;padding:20px;color:#f5f7ff}.post-title{color:#dce6ff}.post-body{color:#c8d0e4}

body.script:
/* عدّل القيم التالية قبل رفع القالب إلى Blogger. */
const CONFIG = { API_BASE: "https://YOUR-SERVICE.onrender.com", GUILD_ID: "YOUR_GUILD_ID", DISCORD_INVITE: "https://discord.gg/YOUR_INVITE" };
const API=CONFIG.API_BASE.replace(/\/$/,"");const $=id=>document.getElementById(id);const safe=s=>String(s??"").replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('year').textContent=new Date().getFullYear();$('joinDiscord').href=CONFIG.DISCORD_INVITE;
function toast(msg){$('toast').textContent=msg;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',4200)}
async function api(path){if(CONFIG.API_BASE.includes('YOUR-SERVICE')||CONFIG.GUILD_ID.includes('YOUR_'))throw new Error('عدّل إعدادات CONFIG في القالب وضع رابط Render ومعرّف السيرفر.');const url=API+path+(path.includes('?')?'&':'?')+'guild_id='+encodeURIComponent(CONFIG.GUILD_ID);const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw new Error('API '+r.status);return r.json()}
async function loadStatus(){try{const d=await api('/api/public/status');$('botDot').classList.toggle('off',!d.bot_online);$('botStatus').textContent=d.bot_online?'البوت متصل':'البوت غير متصل';$('phaseValue').textContent=d.phase_label||'غير معروف';$('waitingValue').textContent=d.waiting_players??0;$('aliveValue').textContent=d.alive_players??0;$('deadValue').textContent=d.dead_players??0;$('minPlayers').textContent=d.min_players??5;$('guildName').textContent=d.guild_name||'Loup-Garou';$('lastUpdate').textContent='آخر تحديث: '+new Date(d.updated_at||Date.now()).toLocaleTimeString('ar');}catch(e){$('botDot').classList.add('off');$('botStatus').textContent='تعذّر الاتصال';$('phaseValue').textContent='غير متاح';$('lastUpdate').innerHTML='<span class="error">'+safe(e.message)+'</span> — تأكد من إعداد رابط Render ومعرّف السيرفر.'}}
async function loadRanking(){try{const d=await api('/api/public/leaderboard?limit=10');const root=$('leaderboard');if(!d.players?.length){root.innerHTML='<div class="empty">لا توجد إحصائيات بعد. العبوا أول جولة لتظهروا هنا.</div>';return}root.innerHTML=d.players.map(p=>`<div class="playerrow"><span class="ranknum">${p.rank<=3?['🥇','🥈','🥉'][p.rank-1]:String(p.rank).padStart(2,'0')}</span><div class="playername">${p.avatar_url?`<img class="avatar" src="${safe(p.avatar_url)}" alt="" loading="lazy">`:'<span class="avatar"></span>'}<div style="min-width:0"><div class="name">${safe(p.name)}</div><div class="sub">${safe(p.level_name||'مبتدئ')} • مستوى ${safe(p.level||1)}</div></div></div><span class="score">⭐ ${safe(p.xp)}</span><span class="score">🏆 ${safe(p.wins)}</span></div>`).join('')}catch(e){$('leaderboard').innerHTML='<div class="empty error">تعذّر تحميل الترتيب. '+safe(e.message)+'</div>'}}
async function loadRoles(){try{const d=await api('/api/public/roles');$('rolesGrid').innerHTML=d.roles.map(r=>`<article class="panel rolecard"><div class="roleimage"><img src="${API+safe(r.image_url)}" alt="بطاقة ${safe(r.name_ar)}" loading="lazy" onerror="this.style.display='none';this.parentElement.innerHTML='<span style=&quot;font-size:52px&quot;>${safe(r.emoji)}</span>'"></div><div class="rolebody"><div class="rolemeta"><span class="pill">${safe(r.team)}</span><span>${safe(r.emoji)}</span></div><h3>${safe(r.name_ar)} <span class="sub">/ ${safe(r.name_en)}</span></h3><p>${safe(r.description)}</p></div></article>`).join('')}catch(e){$('rolesGrid').innerHTML='<div class="panel empty error">تعذّر تحميل بطاقات الأدوار. '+safe(e.message)+'</div>'}}
async function refreshAll(){await Promise.all([loadStatus(),loadRanking(),loadRoles()])}$('refreshBtn').addEventListener('click',()=>refreshAll());refreshAll();setInterval(loadStatus,30000);setInterval(loadRanking,60000);
